// Exports Writ's ABI from the Foundry build into shared/abi/writ.ts, so the
// frontend and scripts don't depend on contracts/out (git-ignored).
// Run after changing Writ.sol: forge build && npm run abi
// test/abi.test.ts fails if the committed file drifts from the build.

import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const abi = JSON.parse(readFileSync(new URL("contracts/out/Writ.sol/Writ.json", root), "utf8")).abi;
writeFileSync(
  new URL("shared/abi/writ.ts", root),
  "// Generated by scripts/export-abi.ts from contracts/out. Do not edit by hand.\n" +
    `export const writAbi = ${JSON.stringify(abi, null, 2)} as const;\n`,
);
console.error(`wrote shared/abi/writ.ts (${abi.length} entries)`);
